const body = $('Webhook Admin (POST)').first().json.body || {};
const token = String(body.token || '');
const acao = String(body.acao || 'listar').toLowerCase();
const reservaId = String(body.reserva_id || '').trim();

if (token !== String($env.FESTAS_ADMIN_TOKEN)) {
  return [{ json: { ok: false, code: 401, erro: 'Token inválido.', _fluxo: 'erro' } }];
}

const reservas = $('Ler Reservas').all().map(i => i.json);

// LISTAR — devolve todas as reservas (para o painel)
if (acao === 'listar') {
  const lista = reservas.map(r => ({
    id: r.id, criado_em: r.criado_em, kit_nome: r.kit_nome,
    data_evento: String(r.data_evento).slice(0,10), periodo: r.periodo,
    cliente_nome: r.cliente_nome, cliente_whatsapp: r.cliente_whatsapp,
    endereco: r.endereco, valor_total: r.valor_total,
    metodo_pagamento: r.metodo_pagamento, status: String(r.status||'').toUpperCase()
  }));
  return [{ json: { ok: true, code: 200, acao, reservas: lista, _fluxo: 'listar' } }];
}

// CONFIRMAR / CANCELAR — precisam de reserva_id
if (!reservaId) return [{ json: { ok:false, code:400, erro:'reserva_id obrigatório.', _fluxo:'erro' } }];
const reserva = reservas.find(r => String(r.id) === reservaId);
if (!reserva) return [{ json: { ok:false, code:404, erro:'Reserva não encontrada.', _fluxo:'erro' } }];

let novoStatus;
if (acao === 'confirmar') novoStatus = 'PAGO';
else if (acao === 'cancelar') novoStatus = 'CANCELADO';
else return [{ json: { ok:false, code:400, erro:'Ação inválida (use confirmar, cancelar ou listar).', _fluxo:'erro' } }];

return [{ json: { ok:true, code:200, acao, novo_status: novoStatus, reserva, _fluxo: 'atualizar' } }];
